        map: glowTexture('rgba(255,230,170,1)', 'rgba(255,160,60,0)'),
        color: 0xffd08a, size: 0.42, transparent: true, depthWrite: false,
        blending: THREE.AdditiveBlending, sizeAttenuation: true,
      })))
