// Pooled particles, tracers, shockwaves, explosions and confetti.
import * as THREE from 'three'
import { glowTexture, rand, pick } from './utils.js'

const MAX_PARTICLES = 520

export class Effects {
  constructor(scene) {
    this.scene = scene
    this.time = 0
    this.tracerPool = []
    this.ringPool = []
    this.flashPool = []
    this.lights = []

    this.initParticles()
    this.initTracers()
    this.initRings()
    this.initFlashes()
    this.initLights()
  }

  initParticles() {
    const geo = new THREE.BufferGeometry()
    this.pPos = new Float32Array(MAX_PARTICLES * 3)
    this.pCol = new Float32Array(MAX_PARTICLES * 3)
    this.pSize = new Float32Array(MAX_PARTICLES)
    this.pAlpha = new Float32Array(MAX_PARTICLES)
    geo.setAttribute('position', new THREE.BufferAttribute(this.pPos, 3).setUsage(THREE.DynamicDrawUsage))
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.pCol, 3).setUsage(THREE.DynamicDrawUsage))
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.pSize, 1).setUsage(THREE.DynamicDrawUsage))
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.pAlpha, 1).setUsage(THREE.DynamicDrawUsage))
    geo.setDrawRange(0, MAX_PARTICLES)

    const mat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: { uMap: { value: glowTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0)') } },
      vertexShader: /* glsl */`
        attribute vec3 aColor;
        attribute float aSize;
        attribute float aAlpha;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = aColor;
          vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (340.0 / max(0.001, -mv.z));
          gl_Position = projectionMatrix * mv;
        }`,
      fragmentShader: /* glsl */`
        uniform sampler2D uMap;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec4 t = texture2D(uMap, gl_PointCoord);
          float a = t.a * vAlpha;
          if (a < 0.01) discard;
          gl_FragColor = vec4(vColor * t.rgb, a);
        }`,
    })
    this.particleMat = mat
    const points = new THREE.Points(geo, mat)
    points.frustumCulled = false
    this.scene.add(points)
    this.points = points
    this.particles = []
    for (let i = 0; i < MAX_PARTICLES; i++) {
      this.particles.push({ alive: false, x: 0, y: -100, z: 0, vx: 0, vy: 0, vz: 0, life: 0, maxLife: 1, size: 1, gravity: -9, drag: 0.98, r: 1, g: 1, b: 1 })
      this.pAlpha[i] = 0
      this.pPos[i * 3 + 1] = -100
    }
    this.pCursor = 0
  }

  spawnParticles(pos, count, opts = {}) {
    const {
      color = 0xffcf3f, color2 = null, speed = 5, spread = 0.6, life = 0.6,
      size = 0.35, gravity = -7, drag = 0.96, up = 1, dir = null,
    } = opts
    const c1 = new THREE.Color(color)
    const c2 = color2 === null ? c1 : new THREE.Color(color2)
    for (let n = 0; n < count; n++) {
      const i = this.pCursor
      this.pCursor = (this.pCursor + 1) % MAX_PARTICLES
      const p = this.particles[i]
      p.alive = true
      p.x = pos.x + rand(-spread, spread) * 0.4
      p.y = pos.y + rand(-spread, spread) * 0.4
      p.z = pos.z + rand(-spread, spread) * 0.4
      let vx = rand(-1, 1)
      let vy = rand(-1, 1) * 0.7 + up
      let vz = rand(-1, 1)
      const l = Math.hypot(vx, vy, vz) || 1
      vx = (vx / l) * speed * rand(0.35, 1)
      vy = (vy / l) * speed * rand(0.35, 1)
      vz = (vz / l) * speed * rand(0.35, 1)
      if (dir) {
        vx = vx * 0.35 + dir.x * speed * rand(0.4, 1)
        vy = vy * 0.35 + dir.y * speed * rand(0.4, 1)
        vz = vz * 0.35 + dir.z * speed * rand(0.4, 1)
      }
      p.vx = vx
      p.vy = vy
      p.vz = vz
      p.maxLife = life * rand(0.65, 1.25)
      p.life = p.maxLife
      p.size = size * rand(0.65, 1.4)
      p.gravity = gravity
      p.drag = drag
      const mix = Math.random()
      const c = c1.clone().lerp(c2, mix)
      p.r = c.r; p.g = c.g; p.b = c.b
      this.pAlpha[i] = 1
      this.pSize[i] = p.size
      this.pCol[i * 3] = c.r
      this.pCol[i * 3 + 1] = c.g
      this.pCol[i * 3 + 2] = c.b
    }
    this.points.geometry.attributes.aColor.needsUpdate = true
    this.points.geometry.attributes.aSize.needsUpdate = true
  }

  initTracers() {
    const geo = new THREE.CylinderGeometry(0.018, 0.018, 1, 4, 1, true)
    geo.translate(0, 0.5, 0)
    for (let i = 0; i < 18; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xffe6a0, transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
        depthWrite: false, side: THREE.DoubleSide,
      })
      const mesh = new THREE.Mesh(geo, mat)
      mesh.visible = false
      mesh.frustumCulled = false
      this.scene.add(mesh)
      this.tracerPool.push({ mesh, life: 0, maxLife: 0.09 })
    }
    this.tracerCursor = 0
  }

  tracer(from, to, color = 0xffe6a0, width = 1) {
    const t = this.tracerPool[this.tracerCursor]
    this.tracerCursor = (this.tracerCursor + 1) % this.tracerPool.length
    const dir = new THREE.Vector3().subVectors(to, from)
    const len = dir.length()
    if (len < 0.01) return
    dir.normalize()
    t.mesh.position.copy(from)
    t.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir)
    t.mesh.scale.set(width, len, width)
    t.mesh.material.color.set(color)
    t.mesh.material.opacity = 1
    t.mesh.visible = true
    t.life = 0.1
  }

  initRings() {
    for (let i = 0; i < 10; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: 0xffcf3f, transparent: true, opacity: 0, side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending, depthWrite: false,
      })
      const mesh = new THREE.Mesh(new THREE.RingGeometry(0.86, 1, 40), mat)
      mesh.visible = false
      mesh.frustumCulled = false
      this.scene.add(mesh)
      this.ringPool.push({ mesh, life: 0, maxLife: 0.6, from: 0.2, to: 4, flat: true })
    }
    this.ringCursor = 0
  }

  ring(pos, { color = 0xffcf3f, from = 0.2, to = 4, life = 0.55, flat = true, opacity = 1 } = {}) {
    const r = this.ringPool[this.ringCursor]
    this.ringCursor = (this.ringCursor + 1) % this.ringPool.length
    r.mesh.position.copy(pos)
    r.mesh.rotation.set(flat ? -Math.PI / 2 : 0, 0, 0)
    r.mesh.material.color.set(color)
    r.mesh.material.opacity = opacity
    r.mesh.visible = true
    r.from = from
    r.to = to
    r.life = life
    r.maxLife = life
    r.opacity = opacity
  }

  initFlashes() {
    const tex = glowTexture('rgba(255,240,200,1)', 'rgba(255,120,30,0)')
    for (let i = 0; i < 8; i++) {
      const mat = new THREE.SpriteMaterial({
        map: tex, color: 0xffd08a, transparent: true, opacity: 0,
        blending: THREE.AdditiveBlending, depthWrite: false,
      })
      const s = new THREE.Sprite(mat)
      s.visible = false
      this.scene.add(s)
      this.flashPool.push({ sprite: s, life: 0, maxLife: 0.12, size: 1 })
    }
    this.flashCursor = 0
  }

  flash(pos, size = 2, color = 0xffd08a, life = 0.12) {
    const f = this.flashPool[this.flashCursor]
    this.flashCursor = (this.flashCursor + 1) % this.flashPool.length
    f.sprite.position.copy(pos)
    f.sprite.material.color.set(color)
    f.sprite.material.opacity = 1
    f.sprite.scale.set(size, size, 1)
    f.sprite.visible = true
    f.life = life
    f.maxLife = life
    f.size = size
  }

  initLights() {
    for (let i = 0; i < 2; i++) {
      const l = new THREE.PointLight(0xff9a4a, 0, 16, 2)
      this.scene.add(l)
      this.lights.push({ light: l, life: 0, maxLife: 0.2, power: 20 })
    }
    this.lightCursor = 0
  }

  lightFlash(pos, power = 25, color = 0xffa04a, life = 0.18) {
    const l = this.lights[this.lightCursor]
    this.lightCursor = (this.lightCursor + 1) % this.lights.length
    l.light.position.copy(pos)
    l.light.color.set(color)
    l.light.intensity = power
    l.power = power
    l.life = life
    l.maxLife = life
  }

  explosion(pos, scale = 1) {
    this.spawnParticles(pos, 34, {
      color: 0xffd76a, color2: 0xff3d2e, speed: 9 * scale, spread: 1.2,
      life: 0.7, size: 0.8, gravity: -5, drag: 0.94,
    })
    this.spawnParticles(pos, 14, {
      color: 0xfff6d8, color2: 0xff9a2e, speed: 4 * scale, spread: 0.6,
      life: 0.45, size: 1.2, gravity: 1, drag: 0.9,
    })
    this.spawnParticles(pos, 10, {
      color: 0x3a3040, color2: 0x1a1420, speed: 3 * scale, spread: 1.4,
      life: 1.4, size: 2.2, gravity: 1.2, drag: 0.9,
    })
    this.flash(pos, 7 * scale, 0xffb35c, 0.16)
    this.ring(pos, { color: 0xffb04a, from: 0.4, to: 7 * scale, life: 0.45, flat: true, opacity: 0.8 })
    this.lightFlash(pos, 60 * scale, 0xff8a3a, 0.3)
  }

  hit(pos, color = 0xffd76a, count = 7) {
    this.spawnParticles(pos, count, {
      color, color2: 0xffffff, speed: 5, spread: 0.25, life: 0.32,
      size: 0.3, gravity: -6, drag: 0.9,
    })
    this.flash(pos, 1.1, color, 0.08)
  }

  muzzle(pos, dir) {
    this.flash(pos, 1.6, 0xffd08a, 0.06)
    this.spawnParticles(pos, 4, {
      color: 0xffd76a, color2: 0xff8a2e, speed: 6, spread: 0.1, life: 0.12,
      size: 0.35, gravity: 0, drag: 0.9, dir,
    })
    this.lightFlash(pos, 14, 0xffb35c, 0.06)
  }

  confetti(center) {
    const colors = [0xffcf3f, 0xff3d8b, 0x2ee6c8, 0xff7a2f, 0xfff6e6, 0x8a5cff]
    for (let i = 0; i < 150; i++) {
      const a = rand(0, Math.PI * 2)
      const r = rand(0, 7)
      const pos = new THREE.Vector3(center.x + Math.cos(a) * r, center.y + rand(2, 12), center.z + Math.sin(a) * r)
      this.spawnParticles(pos, 1, {
        color: pick(colors), speed: rand(1, 4), spread: 0.2, life: rand(2.2, 4.2),
        size: rand(0.16, 0.32), gravity: -3.2, drag: 0.985, up: 0.2,
      })
    }
  }

  update(dt) {
    this.time += dt
    // particles
    let any = false
    for (let i = 0; i < MAX_PARTICLES; i++) {
      const p = this.particles[i]
      if (!p.alive) continue
      any = true
      p.life -= dt
      if (p.life <= 0) {
        p.alive = false
        this.pAlpha[i] = 0
        continue
      }
      p.vy += p.gravity * dt
      const drag = Math.pow(p.drag, dt * 60)
      p.vx *= drag; p.vy *= drag; p.vz *= drag
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt
      if (p.y < 0.04) { p.y = 0.04; p.vy *= -0.32; p.vx *= 0.7; p.vz *= 0.7 }
      this.pPos[i * 3] = p.x
      this.pPos[i * 3 + 1] = p.y
      this.pPos[i * 3 + 2] = p.z
      const t = p.life / p.maxLife
      this.pAlpha[i] = Math.min(1, t * 2.4)
      this.pSize[i] = p.size * (0.5 + t * 0.7)
    }
    if (any) {
      this.points.geometry.attributes.position.needsUpdate = true
      this.points.geometry.attributes.aAlpha.needsUpdate = true
      this.points.geometry.attributes.aSize.needsUpdate = true
    }

    // tracers
    for (const t of this.tracerPool) {
      if (t.life > 0) {
        t.life -= dt
        t.mesh.material.opacity = Math.max(0, t.life / t.maxLife)
        if (t.life <= 0) t.mesh.visible = false
      }
    }

    // rings
    for (const r of this.ringPool) {
      if (r.life > 0) {
        r.life -= dt
        const k = 1 - r.life / r.maxLife
        const s = r.from + (r.to - r.from) * k
        r.mesh.scale.set(s, s, 1)
        r.mesh.material.opacity = r.opacity * Math.pow(1 - k, 1.4)
        if (r.life <= 0) r.mesh.visible = false
      }
    }

    // flashes
    for (const f of this.flashPool) {
      if (f.life > 0) {
        f.life -= dt
        const k = Math.max(0, f.life / f.maxLife)
        f.sprite.material.opacity = k
        const s = f.size * (1.15 - k * 0.15)
        f.sprite.scale.set(s, s, 1)
        if (f.life <= 0) f.sprite.visible = false
      }
    }

    // lights
    for (const l of this.lights) {
      if (l.life > 0) {
        l.life -= dt
        l.light.intensity = l.power * Math.max(0, l.life / l.maxLife)
        if (l.life <= 0) l.light.intensity = 0
      }
    }
  }

  clear() {
    for (let i = 0; i < MAX_PARTICLES; i++) {
      this.particles[i].alive = false
      this.pAlpha[i] = 0
    }
    this.points.geometry.attributes.aAlpha.needsUpdate = true
    for (const t of this.tracerPool) { t.life = 0; t.mesh.visible = false }
    for (const r of this.ringPool) { r.life = 0; r.mesh.visible = false }
    for (const f of this.flashPool) { f.life = 0; f.sprite.visible = false }
    for (const l of this.lights) { l.life = 0; l.light.intensity = 0 }
  }
}

// WebAudio: samba-flavoured procedural soundtrack + berimbau SFX.
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.musicGain = null
    this.sfxGain = null
    this.muted = false
    this.musicTimer = null
    this.nextNote = 0
    this.step = 0
    this.bpm = 102
    this.noiseBuf = null
    this.bossDrone = null
    this.intensity = 1
  }

  init() {
    if (this.ctx) return
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.82
    this.master.connect(this.ctx.destination)

    this.musicGain = this.ctx.createGain()
    this.musicGain.gain.value = 0.3
    this.musicGain.connect(this.master)

    this.sfxGain = this.ctx.createGain()
    this.sfxGain.gain.value = 0.9
    this.sfxGain.connect(this.master)

    // white noise buffer
    const len = this.ctx.sampleRate * 1.2
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const d = buf.getChannelData(0)
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1
    this.noiseBuf = buf
  }

  async unlock() {
    this.init()
    if (!this.ctx) return
    if (this.ctx.state === 'suspended') {
      try { await this.ctx.resume() } catch { /* ignore */ }
    }
    this.startMusic()
  }

  setMuted(m) {
    this.muted = m
    if (this.master) {
      const t = this.ctx.currentTime
      this.master.gain.cancelScheduledValues(t)
      this.master.gain.setTargetAtTime(m ? 0 : 0.82, t, 0.03)
    }
  }

  startMusic() {
    if (!this.ctx || this.musicTimer) return
    this.nextNote = this.ctx.currentTime + 0.1
    this.step = 0
    this.musicTimer = setInterval(() => this.schedule(), 25)
  }

  stopMusic() {
    if (this.musicTimer) clearInterval(this.musicTimer)
    this.musicTimer = null
  }

  schedule() {
    if (!this.ctx || this.muted) return
    const stepDur = 60 / this.bpm / 4
    while (this.nextNote < this.ctx.currentTime + 0.16) {
      this.playStep(this.step, this.nextNote)
      this.nextNote += stepDur
      this.step = (this.step + 1) % 32
    }
  }

  playStep(step, t) {
    const m = this.musicGain
    // surdo — heartbeat of the festa
    if ([0, 6, 8, 14, 16, 22, 24, 30].includes(step)) {
      const o = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      o.type = 'sine'
      o.frequency.setValueAtTime(step % 8 === 0 ? 84 : 70, t)
      o.frequency.exponentialRampToValueAtTime(42, t + 0.18)
      g.gain.setValueAtTime(0.0001, t)
      g.gain.exponentialRampToValueAtTime(0.5, t + 0.008)
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.3)
      o.connect(g); g.connect(m)
      o.start(t); o.stop(t + 0.34)
    }
    // shaker
    if (step % 2 === 1) {
      const src = this.ctx.createBufferSource()
      src.buffer = this.noiseBuf
      const hp = this.ctx.createBiquadFilter()
      hp.type = 'highpass'
      hp.frequency.value = 5200
      const g = this.ctx.createGain()
      const accent = step % 8 === 7 ? 0.09 : 0.045
      g.gain.setValueAtTime(accent, t)
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.06)
      src.connect(hp); hp.connect(g); g.connect(m)
      src.start(t, Math.random() * 0.4, 0.08)
    }
    // agogô
    if ([3, 7, 10, 15, 19, 23, 27, 30].includes(step)) {
      const o = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      o.type = 'triangle'
      o.frequency.setValueAtTime(step % 4 === 3 ? 980 : 740, t)
      g.gain.setValueAtTime(0.0001, t)
      g.gain.exponentialRampToValueAtTime(0.1, t + 0.004)
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.16)
      o.connect(g); g.connect(m)
      o.start(t); o.stop(t + 0.18)
    }
    // bass
    if ([0, 8, 16, 24].includes(step)) {
      const notes = [55, 55, 73.42, 61.74]
      const o = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      o.type = 'triangle'
      o.frequency.setValueAtTime(notes[step / 8], t)
      g.gain.setValueAtTime(0.0001, t)
      g.gain.exponentialRampToValueAtTime(0.14, t + 0.02)
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.42)
      o.connect(g); g.connect(m)
      o.start(t); o.stop(t + 0.45)
    }
    // cavaquinho-ish offbeat
    if ([2, 12, 18, 28].includes(step)) {
      const o = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      o.type = 'square'
      o.frequency.setValueAtTime(step % 16 === 2 ? 293.66 : 392, t)
      g.gain.setValueAtTime(0.0001, t)
      g.gain.exponentialRampToValueAtTime(0.035, t + 0.006)
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.13)
      o.connect(g); g.connect(m)
      o.start(t); o.stop(t + 0.15)
    }
  }

  noise(duration = 0.2, { type = 'lowpass', freq = 900, q = 0.7, gain = 0.2, sweep = 0 } = {}) {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuf
    const f = this.ctx.createBiquadFilter()
    f.type = type
    f.frequency.setValueAtTime(freq, t)
    if (sweep) f.frequency.exponentialRampToValueAtTime(Math.max(60, freq + sweep), t + duration)
    f.Q.value = q
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(gain, t)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    src.connect(f); f.connect(g); g.connect(this.sfxGain)
    src.start(t, Math.random() * 0.5, duration + 0.05)
  }

  tone(freq, dur, { type = 'sine', gain = 0.15, to = null, delay = 0, attack = 0.005 } = {}) {
    if (!this.ctx) return
    const t = this.ctx.currentTime + delay
    const o = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    o.type = type
    o.frequency.setValueAtTime(freq, t)
    if (to) o.frequency.exponentialRampToValueAtTime(Math.max(20, to), t + dur)
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(gain, t + attack)
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    o.connect(g); g.connect(this.sfxGain)
    o.start(t); o.stop(t + dur + 0.03)
  }

  shot() {
    this.tone(330, 0.12, { type: 'triangle', gain: 0.16, to: 150 })
    this.noise(0.07, { type: 'highpass', freq: 1800, gain: 0.1 })
  }
  rocket() {
    this.noise(0.45, { type: 'bandpass', freq: 600, q: 1.4, gain: 0.22, sweep: 900 })
    this.tone(160, 0.4, { type: 'sawtooth', gain: 0.09, to: 60 })
  }
  explosion() {
    this.noise(0.65, { type: 'lowpass', freq: 900, gain: 0.4, sweep: -700 })
    this.tone(70, 0.5, { type: 'sine', gain: 0.35, to: 32 })
  }
  hit() {
    this.tone(880, 0.05, { type: 'square', gain: 0.07, to: 620 })
  }
  kill() {
    this.tone(420, 0.18, { type: 'sawtooth', gain: 0.1, to: 120 })
    this.noise(0.14, { type: 'highpass', freq: 900, gain: 0.06 })
  }
  hurt() {
    this.tone(120, 0.24, { type: 'sine', gain: 0.28, to: 48 })
    this.noise(0.2, { type: 'lowpass', freq: 500, gain: 0.18 })
  }
  pickup() {
    this.tone(660, 0.12, { type: 'sine', gain: 0.13 })
    this.tone(990, 0.18, { type: 'sine', gain: 0.12, delay: 0.08 })
  }
  dash() {
    this.noise(0.26, { type: 'bandpass', freq: 700, q: 1.1, gain: 0.18, sweep: 1600 })
  }
  switchWeapon() {
    this.tone(520, 0.06, { type: 'square', gain: 0.07 })
    this.tone(780, 0.08, { type: 'triangle', gain: 0.08, delay: 0.05 })
  }
  wave() {
    this.tone(740, 0.16, { type: 'triangle', gain: 0.16 })
    this.tone(740, 0.16, { type: 'triangle', gain: 0.14, delay: 0.2 })
    this.tone(988, 0.34, { type: 'triangle', gain: 0.16, delay: 0.4 })
  }
  boss() {
    this.tone(110, 1.2, { type: 'sawtooth', gain: 0.16, to: 55, attack: 0.15 })
    this.noise(1.0, { type: 'lowpass', freq: 300, gain: 0.14 })
  }
  waveClear() {
    this.tone(523, 0.12, { type: 'sine', gain: 0.12 })
    this.tone(659, 0.12, { type: 'sine', gain: 0.12, delay: 0.1 })
    this.tone(784, 0.24, { type: 'sine', gain: 0.13, delay: 0.2 })
  }
  win() {
    const notes = [523, 659, 784, 1046, 1318]
    notes.forEach((n, i) => this.tone(n, 0.5, { type: 'triangle', gain: 0.14, delay: i * 0.13 }))
    this.tone(261, 1.4, { type: 'sine', gain: 0.12, delay: 0.1 })
  }
  gameOver() {
    const notes = [392, 329, 261, 196]
    notes.forEach((n, i) => this.tone(n, 0.6, { type: 'triangle', gain: 0.14, delay: i * 0.18 }))
  }
  setBossMode(on) {
    if (!this.ctx) return
    if (on && !this.bossDrone) {
      const o = this.ctx.createOscillator()
      const g = this.ctx.createGain()
      o.type = 'sawtooth'
      o.frequency.value = 48
      g.gain.value = 0.0001
      g.gain.setTargetAtTime(0.055, this.ctx.currentTime, 0.4)
      o.connect(g); g.connect(this.master)
      o.start()
      this.bossDrone = { o, g }
    } else if (!on && this.bossDrone) {
      const { o, g } = this.bossDrone
      g.gain.setTargetAtTime(0.0001, this.ctx.currentTime, 0.2)
      o.stop(this.ctx.currentTime + 0.8)
      this.bossDrone = null
    }
  }
  reset() {
    this.setBossMode(false)
  }
}

// Unified keyboard / mouse / touch / gyro input.
import { clamp } from './utils.js'

const DEG = Math.PI / 180

export class Input {
  constructor(canvas, { onPause, onTiltStatus } = {}) {
    this.canvas = canvas
    this.onPause = onPause
    this.onTiltStatus = onTiltStatus
    this.keys = new Set()
    this.lookX = 0
    this.lookY = 0
    this.move = { x: 0, y: 0 }
    this.firing = false
    this.dashQueued = false
    this.switchQueued = false
    this.sensitivity = 1
    this.enabled = false
    this.touch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0 || matchMedia('(pointer: coarse)').matches
    this.lookPointer = null
    this.stickPointer = null
    this.stick = { active: false, ox: 0, oy: 0, radius: 46, dx: 0, dy: 0 }
    this.tiltEnabled = false
    this.tiltAvailable = typeof DeviceMotionEvent !== 'undefined'
    this.tiltSeen = false
    this.tiltStatusTimer = null
    this.rot = { a: 0, b: 0, g: 0 }
    this.gyroGain = 0.0115
    this.pointerLocked = false

    this.bindKeyboard()
    this.bindMouse()
    this.bindTouch()
    this.bindTilt()
  }

  /* ------------------------------------------------------- keyboard */
  bindKeyboard() {
    window.addEventListener('keydown', (e) => {
      const k = e.key.toLowerCase()
      this.keys.add(k)
      if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(k)) e.preventDefault()
      if (!this.enabled) return
      if (k === 'escape') this.onPause?.()
      if (k === 'shift') this.dashQueued = true
      if (k === 'q' || k === 'tab') { e.preventDefault(); this.switchQueued = true }
      if (k === '1' || k === '2') this.switchQueued = true
    })
    window.addEventListener('keyup', (e) => this.keys.delete(e.key.toLowerCase()))
    window.addEventListener('blur', () => { this.keys.clear(); this.firing = false })
  }

  /* ---------------------------------------------------------- mouse */
  bindMouse() {
    this.canvas.addEventListener('mousedown', (e) => {
      if (!this.enabled || this.touch || e.button !== 0) return
      if (!this.pointerLocked) {
        this.canvas.requestPointerLock?.()
        return
      }
      this.firing = true
    })
    window.addEventListener('mouseup', () => { this.firing = false })
    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === this.canvas
      if (!this.pointerLocked && this.enabled && !this.touch) this.onPause?.()
    })
    document.addEventListener('mousemove', (e) => {
      if (!this.enabled || this.touch) return
      if (this.pointerLocked) {
        this.lookX += e.movementX * 0.0023 * this.sensitivity
        this.lookY += e.movementY * 0.0023 * this.sensitivity
      }
    })
    // drag-look fallback when pointer lock is unavailable
    let dragging = false
    this.canvas.addEventListener('pointerdown', (e) => {
      if (!this.enabled || this.touch || e.pointerType === 'mouse' && this.pointerLocked) return
      if (e.pointerType === 'mouse' && e.button === 0) dragging = true
    })
    window.addEventListener('pointermove', (e) => {
      if (dragging && !this.pointerLocked && this.enabled) {
        this.lookX += e.movementX * 0.0023 * this.sensitivity
        this.lookY += e.movementY * 0.0023 * this.sensitivity
      }
    })
    window.addEventListener('pointerup', () => { dragging = false })
  }

  /* ---------------------------------------------------------- touch */
  bindTouch() {
    // Look drag anywhere on the canvas.
    this.canvas.addEventListener('pointerdown', (e) => {
      if (!this.enabled || e.pointerType === 'mouse') return
      if (this.lookPointer !== null) return
      this.lookPointer = e.pointerId
      this.lastLook = { x: e.clientX, y: e.clientY }
      this.canvas.setPointerCapture?.(e.pointerId)
    })
    this.canvas.addEventListener('pointermove', (e) => {
      if (e.pointerId !== this.lookPointer) return
      const dx = e.clientX - this.lastLook.x
      const dy = e.clientY - this.lastLook.y
      this.lastLook = { x: e.clientX, y: e.clientY }
      this.lookX += dx * 0.0042 * this.sensitivity
      this.lookY += dy * 0.0042 * this.sensitivity
    })
    const endLook = (e) => {
      if (e.pointerId === this.lookPointer) this.lookPointer = null
    }
    this.canvas.addEventListener('pointerup', endLook)
    this.canvas.addEventListener('pointercancel', endLook)

    // Dynamic joystick.
    const zone = document.getElementById('stick-zone')
    const base = document.getElementById('stick-base')
    const knob = document.getElementById('stick-knob')
    if (!zone || !base || !knob) return
    const setKnob = (dx, dy) => {
      knob.style.transform = `translate(${dx}px, ${dy}px)`
    }
    zone.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return
      e.preventDefault()
      this.stickPointer = e.pointerId
      const zr = zone.getBoundingClientRect()
      const lx = clamp(e.clientX - zr.left, 66, zr.width - 66)
      const lb = clamp(zr.bottom - e.clientY, 66, zr.height - 66)
      base.style.left = `${lx}px`
      base.style.bottom = `${lb}px`
      base.classList.add('active')
      this.stick = { active: true, ox: e.clientX, oy: e.clientY, radius: 46, dx: 0, dy: 0 }
      setKnob(0, 0)
      zone.setPointerCapture?.(e.pointerId)
    })
    zone.addEventListener('pointermove', (e) => {
      if (e.pointerId !== this.stickPointer || !this.stick.active) return
      let dx = e.clientX - this.stick.ox
      let dy = e.clientY - this.stick.oy
      const len = Math.hypot(dx, dy)
      const r = this.stick.radius
      if (len > r) { dx = (dx / len) * r; dy = (dy / len) * r }
      this.stick.dx = dx / r
      this.stick.dy = dy / r
      setKnob(dx, dy)
      this.move.x = dx / r
      this.move.y = -dy / r
    })
    const endStick = (e) => {
      if (e.pointerId !== this.stickPointer) return
      this.stickPointer = null
      this.stick.active = false
      this.move.x = 0
      this.move.y = 0
      setKnob(0, 0)
      base.classList.remove('active')
    }
    zone.addEventListener('pointerup', endStick)
    zone.addEventListener('pointercancel', endStick)

    // Fire button.
    const fire = document.getElementById('btn-fire')
    if (fire) {
      fire.addEventListener('pointerdown', (e) => {
        if (!this.enabled) return
        e.preventDefault()
        e.stopPropagation()
        this.firing = true
        fire.classList.add('pressed')
        fire.setPointerCapture?.(e.pointerId)
      })
      const stopFire = (e) => {
        e.preventDefault()
        this.firing = false
        fire.classList.remove('pressed')
      }
      fire.addEventListener('pointerup', stopFire)
      fire.addEventListener('pointercancel', stopFire)
      fire.addEventListener('pointerleave', (e) => {
        if (e.buttons === 0) { this.firing = false; fire.classList.remove('pressed') }
      })
    }
    const dash = document.getElementById('btn-dash')
    dash?.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return
      e.preventDefault(); e.stopPropagation()
      this.dashQueued = true
    })
    const swap = document.getElementById('btn-switch')
    swap?.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return
      e.preventDefault(); e.stopPropagation()
      this.switchQueued = true
    })
  }

  /* ----------------------------------------------------------- tilt */
  bindTilt() {
    this.tiltHandler = (e) => {
      if (!this.tiltEnabled) return
      const rr = e.rotationRate
      if (!rr || (rr.alpha == null && rr.beta == null && rr.gamma == null)) return
      this.tiltSeen = true
      const a = rr.alpha || 0
      const b = rr.beta || 0
      const g = rr.gamma || 0
      // smooth gyro
      this.rot.a += (a - this.rot.a) * 0.35
      this.rot.b += (b - this.rot.b) * 0.35
      this.rot.g += (g - this.rot.g) * 0.35
    }
    window.addEventListener('devicemotion', this.tiltHandler)
    this.recalibrate = () => { this.rot.a = this.rot.b = this.rot.g = 0 }
    window.addEventListener('orientationchange', () => setTimeout(() => this.recalibrate(), 300))
    screen.orientation?.addEventListener?.('change', () => setTimeout(() => this.recalibrate(), 300))
  }

  async enableTilt() {
    if (this.tiltEnabled) {
      this.recalibrate()
      return true
    }
    if (typeof DeviceMotionEvent === 'undefined') {
      this.onTiltStatus?.('unsupported')
      return false
    }
    try {
      if (typeof DeviceMotionEvent.requestPermission === 'function') {
        const res = await DeviceMotionEvent.requestPermission()
        if (res !== 'granted') {
          this.onTiltStatus?.('denied')
          return false
        }
      }
    } catch {
      this.onTiltStatus?.('denied')
      return false
    }
    this.tiltEnabled = true
    this.tiltSeen = false
    this.recalibrate()
    this.onTiltStatus?.('enabled')
    clearTimeout(this.tiltStatusTimer)
    this.tiltStatusTimer = setTimeout(() => {
      if (!this.tiltSeen) this.onTiltStatus?.('silent')
    }, 1600)
    return true
  }

  disableTilt() {
    this.tiltEnabled = false
    this.onTiltStatus?.('disabled')
  }

  /* --------------------------------------------------------- update */
  update(dt) {
    if (!this.enabled) return
    if (this.tiltEnabled) {
      const angle = screen.orientation?.angle ?? window.orientation ?? 0
      let up, right
      if (angle === 90) { up = [1, 0, 0]; right = [0, -1, 0] }
      else if (angle === 270 || angle === -90) { up = [-1, 0, 0]; right = [0, 1, 0] }
      else if (angle === 180) { up = [0, -1, 0]; right = [-1, 0, 0] }
      else { up = [0, 1, 0]; right = [1, 0, 0] }
      const { a, b, g } = this.rot
      const yawRate = a * up[0] + b * up[1] + g * up[2]
      const pitchRate = a * right[0] + b * right[1] + g * right[2]
      const dead = (v) => Math.abs(v) < 0.8 ? 0 : v
      const gain = this.gyroGain * this.sensitivity * dt * DEG
      this.lookX -= dead(yawRate) * gain
      this.lookY += dead(pitchRate) * gain
      // decay stale rates so a stopped phone stops aiming
      const decay = Math.exp(-dt * 6)
      this.rot.a *= decay
      this.rot.b *= decay
      this.rot.g *= decay
    }
  }

  consumeLook() {
    const x = this.lookX
    const y = this.lookY
    this.lookX = 0
    this.lookY = 0
    return [x, y]
  }

  consumeDash() {
    const v = this.dashQueued
    this.dashQueued = false
    return v
  }

  consumeSwitch() {
    const v = this.switchQueued
    this.switchQueued = false
    return v
  }

  getMove() {
    let x = this.move.x
    let y = this.move.y
    if (this.keys.has('w') || this.keys.has('arrowup')) y += 1
    if (this.keys.has('s') || this.keys.has('arrowdown')) y -= 1
    if (this.keys.has('a') || this.keys.has('arrowleft')) x -= 1
    if (this.keys.has('d') || this.keys.has('arrowright')) x += 1
    const len = Math.hypot(x, y)
    if (len > 1) { x /= len; y /= len }
    return { x, y }
  }

  isFiring() {
    return this.firing || (this.keys.has(' ') && this.enabled)
  }

  setEnabled(v) {
    this.enabled = v
    if (!v) {
      this.firing = false
      this.move.x = 0
      this.move.y = 0
      this.keys.clear()
      this.dashQueued = false
      this.switchQueued = false
      document.getElementById('stick-base')?.classList.remove('active')
    }
  }

  releasePointerLock() {
    if (document.pointerLockElement) document.exitPointerLock?.()
  }
}

// First-person guardian: movement, dash, camera feel and vitals.
import * as THREE from 'three'
import { clamp, damp, rand } from './utils.js'

const EYE = 1.68

export class Player {
  constructor(camera, world, input, audio) {
    this.camera = camera
    this.world = world
    this.input = input
    this.audio = audio
    camera.rotation.order = 'YXZ'
    this.position = new THREE.Vector3(0, 0, 12)
    this.velocity = new THREE.Vector3()
    this.yaw = 0
    this.pitch = -0.02
    this.roll = 0
    this.bobTime = 0
    this.bob = 0
    this.lookVel = { x: 0, y: 0 }
    this.recoilPitch = 0
    this.recoilYaw = 0
    this.shake = 0
    this.maxHealth = 100
    this.maxShield = 50
    this.onDamage = null
    this.onDeath = null
    this.onDash = null
    this.reset()
  }

  reset() {
    this.position.set(0, 0, 12)
    this.velocity.set(0, 0, 0)
    this.yaw = 0
    this.pitch = -0.02
    this.roll = 0
    this.health = this.maxHealth
    this.shield = 0
    this.dead = false
    this.invuln = 0
    this.dashTime = 0
    this.dashCooldown = 0
    this.dashDir = new THREE.Vector3()
    this.recoilPitch = 0
    this.recoilYaw = 0
    this.shake = 0
    this.bob = 0
    this.bobTime = 0
    this.lookVel.x = 0
    this.lookVel.y = 0
    this.fovKick = 0
    this.speedRatio = 0
    this.applyCamera(0)
  }

  get eyePosition() {
    return new THREE.Vector3(this.position.x, EYE + this.bob, this.position.z)
  }

  get aimDirection() {
    const d = new THREE.Vector3()
    this.camera.getWorldDirection(d)
    return d
  }

  forwardVector() {
    return new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw))
  }

  rightVector() {
    return new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw))
  }

  addRecoil(pitch, yaw = 0) {
    this.recoilPitch += pitch
    this.recoilYaw += yaw
  }

  update(dt) {
    if (this.dead) {
      this.applyCamera(dt)
      return
    }
    const input = this.input
    const [lx, ly] = input.consumeLook()
    this.lookVel.x = damp(this.lookVel.x, lx / Math.max(dt, 0.001), 10, dt)
    this.lookVel.y = damp(this.lookVel.y, ly / Math.max(dt, 0.001), 10, dt)

    this.yaw -= lx
    this.pitch -= ly
    this.pitch = clamp(this.pitch, -1.28, 1.15)

    // dash
    this.dashCooldown = Math.max(0, this.dashCooldown - dt)
    if (input.consumeDash() && this.dashCooldown <= 0 && this.dashTime <= 0) {
      const mv = input.getMove()
      const dir = this.forwardVector().multiplyScalar(mv.y || 1).add(this.rightVector().multiplyScalar(mv.x))
      if (dir.lengthSq() < 0.01) dir.copy(this.forwardVector())
      dir.normalize()
      this.dashDir.copy(dir)
      this.dashTime = 0.22
      this.dashCooldown = 2.1
      this.invuln = Math.max(this.invuln, 0.34)
      this.onDash?.()
    }

    // movement
    const mv = input.getMove()
    const speed = 5.1
    let desired = new THREE.Vector3()
    if (this.dashTime > 0) {
      this.dashTime -= dt
      const k = clamp(this.dashTime / 0.22, 0, 1)
      desired.copy(this.dashDir).multiplyScalar(15.5 * (0.45 + k * 0.55))
      this.invuln = Math.max(this.invuln, 0.05)
    } else {
      desired.copy(this.forwardVector()).multiplyScalar(mv.y * speed)
      desired.add(this.rightVector().multiplyScalar(mv.x * speed))
    }
    const accel = this.dashTime > 0 ? 30 : 13
    this.velocity.x = damp(this.velocity.x, desired.x, accel, dt)
    this.velocity.z = damp(this.velocity.z, desired.z, accel, dt)
    this.position.x += this.velocity.x * dt
    this.position.z += this.velocity.z * dt
    this.world.collide(this.position, 0.44)

    const moving = Math.hypot(this.velocity.x, this.velocity.z)
    this.speedRatio = damp(this.speedRatio, clamp(moving / speed, 0, 1.4), 8, dt)
    this.bobTime += dt * (5.5 + this.speedRatio * 5.5)
    this.bob = Math.sin(this.bobTime) * 0.028 * this.speedRatio

    this.invuln = Math.max(0, this.invuln - dt)
    this.shake = Math.max(0, this.shake - dt * 2.4)
    this.recoilPitch = damp(this.recoilPitch, 0, 9, dt)
    this.recoilYaw = damp(this.recoilYaw, 0, 9, dt)

    // strafe roll
    const strafe = input.getMove().x
    this.roll = damp(this.roll, -strafe * 0.018 - this.lookVel.x * 0.0006, 6, dt)
    this.fovKick = damp(this.fovKick, this.dashTime > 0 ? 7 : 0, 10, dt)

    this.applyCamera(dt)
  }

  applyCamera() {
    const bobY = this.bob
    const shakeX = this.shake > 0 ? rand(-1, 1) * this.shake * 0.035 : 0
    const shakeY = this.shake > 0 ? rand(-1, 1) * this.shake * 0.035 : 0
    this.camera.position.set(
      this.position.x + Math.cos(this.yaw) * 0.03,
      EYE + bobY + shakeY,
      this.position.z - Math.sin(this.yaw) * 0.03
    )
    this.camera.rotation.set(
      this.pitch + this.recoilPitch + shakeX,
      this.yaw + this.recoilYaw,
      this.roll
    )
    const targetFov = (this.input.touch ? 82 : 78) + this.fovKick
    if (Math.abs(this.camera.fov - targetFov) > 0.01) {
      this.camera.fov = damp(this.camera.fov, targetFov, 10, 0.016)
      this.camera.updateProjectionMatrix()
    }
  }

  takeDamage(amount, sourcePos = null) {
    if (this.dead || this.invuln > 0) return 0
    let dmg = amount
    if (this.shield > 0) {
      const absorbed = Math.min(this.shield, dmg)
      this.shield -= absorbed
      dmg -= absorbed
    }
    this.health = Math.max(0, this.health - dmg)
    this.invuln = 0.55
    this.shake = 1
    if (sourcePos) {
      const dx = sourcePos.x - this.position.x
      const dz = sourcePos.z - this.position.z
      this.recoilYaw += clamp((Math.atan2(-dx, -dz) - this.yaw) * 0.08, -0.05, 0.05)
    }
    this.onDamage?.(dmg)
    if (this.health <= 0) {
      this.dead = true
      this.onDeath?.()
    }
    return dmg
  }

  heal(amount) {
    const before = this.health
    this.health = Math.min(this.maxHealth, this.health + amount)
    return this.health - before
  }

  addShield(amount) {
    const before = this.shield
    this.shield = Math.min(this.maxShield, this.shield + amount)
    return this.shield - before
  }

  get healthPct() { return this.health / this.maxHealth }
  get shieldPct() { return this.shield / this.maxShield }
  get dashReady() { return this.dashCooldown <= 0 }
  get dashPct() { return 1 - clamp(this.dashCooldown / 2.1, 0, 1) }
}

// Enemies: carnival masks, Saci rushers, Boi-Bumbá chargers and the Trio Elétrico.
import * as THREE from 'three'
import { rand, pick, clamp, angleLerp, canvasTexture, glowTexture, textTexture, TAU } from './utils.js'

let boiTexture = null
function getBoiTexture() {
  if (boiTexture) return boiTexture
  boiTexture = canvasTexture(256, 128, (ctx, w, h) => {
    ctx.fillStyle = '#1c1030'
    ctx.fillRect(0, 0, w, h)
    const cols = ['#ff3d8b', '#ffcf3f', '#2ee6c8', '#ff7a2f', '#8a5cff']
    for (let i = 0; i < 10; i++) {
      ctx.fillStyle = cols[i % cols.length]
      ctx.beginPath()
      const x = i * 28
      ctx.moveTo(x, h / 2)
      ctx.lineTo(x + 14, h / 2 - 22)
      ctx.lineTo(x + 28, h / 2)
      ctx.lineTo(x + 14, h / 2 + 22)
      ctx.closePath()
      ctx.fill()
    }
    ctx.fillStyle = 'rgba(255,255,255,0.08)'
    for (let i = 0; i < 40; i++) ctx.fillRect(rand(0, w), rand(0, h), 2, 2)
  })
  boiTexture.wrapS = boiTexture.wrapT = THREE.RepeatWrapping
  boiTexture.repeat.set(2, 1)
  return boiTexture
}

class Enemy {
  constructor(game, type, pos) {
    this.game = game
    this.type = type
    this.dead = false
    this.flash = 0
    this.spawnT = 0
    this.age = 0
    this.attackTimer = rand(0.8, 2.2)
    this.group = new THREE.Group()
    this.group.position.copy(pos)
    this.baseY = 0
    this.knock = new THREE.Vector3()
    this.materials = []
  }

  addMat(m) { this.materials.push(m); return m }

  updateFlash(dt) {
    this.flash = Math.max(0, this.flash - dt * 4)
    const s = 1 + this.flash * 0.09
    this.group.scale.setScalar(this.spawnScale * s)
  }

  takeDamage(amount, point) {
    if (this.dead || this.dying) return false
    this.hp -= amount
    this.flash = 1
    this.game.effects.hit(point || this.center(), this.hitColor || 0xffd76a, 6)
    this.game.audio.hit()
    if (this.hp <= 0) {
      this.die()
      return true
    }
    return false
  }

  die() {
    this.dead = true
    this.game.effects.explosion(this.center(), this.type === 'boi' ? 1.5 : 1)
    this.game.audio.kill()
    this.game.onEnemyKilled?.(this)
    this.game.world.scene.remove(this.group)
    this.dispose()
  }

  dispose() {
    this.group.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.()
      if (o.material) {
        const ms = Array.isArray(o.material) ? o.material : [o.material]
        ms.forEach((m) => m.dispose?.())
      }
    })
  }

  center() {
    return new THREE.Vector3(this.group.position.x, this.group.position.y + (this.hitY || 1), this.group.position.z)
  }
}

/* ============================================================ MÁSCARA */
class Mask extends Enemy {
  constructor(game, pos) {
    super(game, 'mask', pos)
    this.hp = 30
    this.maxHp = 30
    this.hitY = 2.9
    this.hitRadius = 0.95
    this.hitColor = 0xff7ab8
    this.score = 100
    this.spawnScale = 0
    this.preferred = rand(12, 17)
    this.orbitDir = Math.random() < 0.5 ? 1 : -1
    this.baseY = rand(2.4, 3.4)
    this.warn = 0
    this.build()
  }

  build() {
    const faceMat = this.addMat(new THREE.MeshLambertMaterial({ color: 0xffe6cf, emissive: 0x431d2d, emissiveIntensity: 0.7 }))
    const face = new THREE.Mesh(new THREE.SphereGeometry(0.55, 14, 11), faceMat)
    face.scale.set(1, 1.18, 0.34)
    this.group.add(face)

    const socketMat = this.addMat(new THREE.MeshBasicMaterial({ color: 0x1a0812 }))
    for (const sx of [-0.19, 0.19]) {
      const eye = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), socketMat)
      eye.scale.set(1, 1.25, 0.4)
      eye.position.set(sx, 0.1, 0.2)
      this.group.add(eye)
      const pupil = new THREE.Mesh(new THREE.SphereGeometry(0.055, 7, 6), new THREE.MeshBasicMaterial({ color: 0xff5aa8 }))
      pupil.position.set(sx, 0.1, 0.245)
      this.group.add(pupil)
    }
    const mouth = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.07, 0.08), socketMat)
    mouth.position.set(0, -0.22, 0.22)
    this.group.add(mouth)
    // feather crown
    const featherCols = [0xff3d8b, 0xffcf3f, 0x2ee6c8, 0xff7a2f, 0x8a5cff]
    for (let i = 0; i < 7; i++) {
      const a = (i / 7) * TAU
      const feather = new THREE.Mesh(new THREE.ConeGeometry(0.09, rand(0.7, 1.1), 4), new THREE.MeshLambertMaterial({ color: pick(featherCols), emissive: 0x221018, emissiveIntensity: 0.4 }))
      feather.position.set(Math.cos(a) * 0.35, 0.55 + Math.sin(a * 2) * 0.08, -0.05)
      feather.rotation.z = Math.cos(a) * 0.9
      feather.rotation.x = Math.sin(a) * 0.9 - 0.2
      this.group.add(feather)
    }
    // halo ring
    const halo = new THREE.Mesh(new THREE.TorusGeometry(0.75, 0.025, 4, 32), new THREE.MeshBasicMaterial({ color: 0xff5aa8, transparent: true, opacity: 0.65 }))
    halo.rotation.x = Math.PI / 2.2
    halo.position.z = -0.15
    this.group.add(halo)
    this.halo = halo

    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(255,120,190,0.85)', 'rgba(255,40,120,0)'),
      color: 0xff6ab4, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0.7,
    }))
    glow.scale.set(2.4, 2.4, 1)
    this.group.add(glow)

    this.group.position.y = this.baseY
    this.game.world.scene.add(this.group)
    this.game.effects.ring(this.group.position, { color: 0xff5aa8, from: 0.2, to: 2.4, life: 0.5, flat: true })
  }

  update(dt) {
    this.age += dt
    this.spawnT = Math.min(1, this.spawnT + dt * 3)
    this.spawnScale = this.spawnT
    this.updateFlash(dt)
    const p = this.game.player.position
    const dx = p.x - this.group.position.x
    const dz = p.z - this.group.position.z
    const dist = Math.hypot(dx, dz) || 0.001
    const nx = dx / dist
    const nz = dz / dist

    // keep preferred distance and orbit
    let radial = 0
    if (dist > this.preferred + 2) radial = 1
    else if (dist < this.preferred - 2) radial = -1
    const speed = 2.6
    const tx = nx * radial + -nz * this.orbitDir * 0.7
    const tz = nz * radial + nx * this.orbitDir * 0.7
    const tl = Math.hypot(tx, tz) || 1
    this.group.position.x += (tx / tl) * speed * dt
    this.group.position.z += (tz / tl) * speed * dt
    const r = Math.hypot(this.group.position.x, this.group.position.z)
    if (r > 24) {
      this.group.position.x *= 24 / r
      this.group.position.z *= 24 / r
    }
    this.group.position.y = this.baseY + Math.sin(this.age * 1.6 + this.hitRadius) * 0.22
    this.group.lookAt(p.x, this.group.position.y, p.z)
    this.halo.rotation.z += dt * 1.4

    // attack
    this.attackTimer -= dt
    if (this.attackTimer <= 0 && this.warn <= 0) {
      this.warn = 0.55
    }
    if (this.warn > 0) {
      this.warn -= dt
      this.halo.scale.setScalar(1 + (1 - this.warn / 0.55) * 0.5)
      if (this.warn <= 0) {
        this.halo.scale.setScalar(1)
        this.fire()
        this.attackTimer = rand(2.2, 3.2)
      }
    }
  }

  fire() {
    const origin = this.center()
    const target = this.game.player.eyePosition
    const dir = target.sub(origin).normalize()
    this.game.enemies.spawnProjectile(origin, dir, { speed: 10.5, damage: 10, color: 0xff5aa8, owner: this })
    this.game.effects.flash(origin, 1.8, 0xff8ac4, 0.12)
  }
}

