    cap.position.y = 1.85
    cap.rotation.z = 0.2
    this.group.add(cap)
    const capTip = new THREE.Mesh(new THREE.SphereGeometry(0.09, 6, 5), red)
    capTip.position.set(0.08, 2.12, 0)
