    this.hitRadius = 1.15
    this.hitColor = 0xffcf3f
    this.score = 280
    this.spawnScale = 0
    this.state = 'idle'
    this.stateT = 0
    this.chargeDir = new THREE.Vector3()
    this.stun = 0
    this.build()
  }

  build() {
    const tex = getBoiTexture()
    const bodyMat = this.addMat(new THREE.MeshLambertMaterial({ map: tex, color: 0xffffff, emissive: 0x1a0e22, emissiveIntensity: 0.6 }))
    const dark = this.addMat(new THREE.MeshLambertMaterial({ color: 0x2a1a2a }))
