    }))
    beaconGlow.position.set(0, 6.6, 0.4)
    beaconGlow.scale.set(3, 3, 1)
    this.group.add(beaconGlow)
    this.beaconGlow = beaconGlow

    this.group.position.set(this.base.x, 0, -34)
    this.game.world.scene.add(this.group)
  }

  update(dt) {
    this.age += dt
    const p = this.game.player.position
    if (this.entering) {
      this.enterT += dt
      const k = clamp(this.enterT / 2.6, 0, 1)
      const e = 1 - Math.pow(1 - k, 3)
      this.group.position.set(0, Math.sin(k * Math.PI) * 0.2, -34 + e * 14)
      if (k >= 1) {
        this.entering = false
        this.base.set(0, 0, -20)
        this.game.audio.boss()
      }
      this.group.lookAt(p.x, 2, p.z)
      return
    }
    if (this.dying) {
      this.deathT += dt
      this.group.position.x = Math.sin(this.deathT * 26) * 0.25
      if (Math.random() < dt * 9) {
        const pt = this.group.position.clone().add(new THREE.Vector3(rand(-4, 4), rand(1, 6), rand(-2, 2)))
        this.game.effects.explosion(pt, rand(0.8, 1.6))
        this.game.audio.explosion()
      }
      if (this.deathT > 2.8) {
        this.dead = true
        this.game.onBossDefeated?.()
      }
      return
    }

    // slow drift across the plaza
    this.group.position.x = Math.sin(this.age * 0.42) * 7.5
    this.group.position.z = -20 + Math.cos(this.age * 0.31) * 1.6
    this.group.position.y = Math.abs(Math.sin(this.age * 1.8)) * 0.04
    this.group.lookAt(p.x, 2, p.z)
    this.beacon.rotation.y += dt * 5
    this.beaconGlow.material.opacity = 0.7 + Math.sin(this.age * 8) * 0.3

    const hpPct = this.hp / this.maxHp
    this.volley -= dt
    if (this.volley <= 0 && this.warn <= 0) {
      this.warn = 1.0
      this.volley = hpPct < 0.4 ? 2.5 : 3.4
    }
    if (this.warn > 0) {
      this.warn -= dt
      const pulse = 1 + Math.sin(this.age * 40) * 0.2
      this.beaconGlow.scale.set(3 * pulse, 3 * pulse, 1)
      if (this.warn <= 0) {
        this.fireVolley()
      }
    }

    this.spawnTimer -= dt
    if (this.spawnTimer <= 0) {
      this.spawnTimer = 7.5
      const n = this.game.enemies.countOfType('mask')
      if (n < 2) {
        for (let i = 0; i < 2; i++) {
          const pos = this.group.position.clone().add(new THREE.Vector3(rand(-6, 6), 0, rand(-2, 4)))
          this.game.enemies.spawn('mask', pos)
        }
      }
    }

    // damage smoke
    if (hpPct < 0.5 && Math.random() < dt * 8) {
      const pt = this.group.position.clone().add(new THREE.Vector3(rand(-3.5, 3.5), rand(3, 6), rand(-1.5, 1.5)))
      this.game.effects.spawnParticles(pt, 2, { color: 0x2a2030, color2: 0x0f0a14, speed: 1.4, spread: 0.4, life: 1.4, size: 1.5, gravity: 0.8, drag: 0.95 })
    }
  }

  fireVolley() {
    const base = this.group.position.clone()
    const forward = new THREE.Vector3(pForwardX(this), 0, pForwardZ(this)).normalize()
    this.game.effects.flash(base.clone().add(new THREE.Vector3(0, 4, 1)), 7, 0xff5aa8, 0.2)
    this.game.effects.ring(base.clone().add(new THREE.Vector3(0, 0.9, 0)), { color: 0xff3d8b, from: 1, to: 8, life: 0.5, flat: true })
    this.game.enemies.spawnShockwave(base, { damage: 14, speed: 9.5, maxRadius: 36, color: 0xff3d8b })
    this.game.audio.tone(70, 0.8, { type: 'sawtooth', gain: 0.2, to: 40 })
    this.game.audio.noise(0.6, { type: 'lowpass', freq: 500, gain: 0.22 })
    this.game.player.shake = Math.max(this.game.player.shake, 0.5)
  }

  takeDamage(amount, point) {
    if (this.dying) return false
    return super.takeDamage(amount, point)
  }

  die() {
    if (this.dying) return
    this.dying = true
    this.deathT = 0
    this.hp = 0
    this.game.onBossHp?.(0)
    this.game.audio.explosion()
    this.game.effects.confetti(this.group.position.clone().add(new THREE.Vector3(0, 4, 0)))
  }
}

function pForwardX(e) {
  const v = new THREE.Vector3()
  e.group.getWorldDirection(v)
  return v.x
}
function pForwardZ(e) {
  const v = new THREE.Vector3()
  e.group.getWorldDirection(v)
  return v.z
}

/* ====================================================== MANAGER */
export class EnemyManager {
  constructor(game) {
    this.game = game
    this.list = []
    this.projectiles = []
    this.shockwaves = []
    this.boss = null
  }

  reset() {
    for (const e of this.list) {
      this.game.world.scene.remove(e.group)
      e.dispose?.()
    }
    this.list.length = 0
    for (const p of this.projectiles) this.game.world.scene.remove(p.mesh)
    this.projectiles.length = 0
    for (const s of this.shockwaves) this.game.world.scene.remove(s.mesh)
    this.shockwaves.length = 0
    this.boss = null
  }

  spawn(type, pos) {
    let e
    if (type === 'mask') e = new Mask(this.game, pos)
    else if (type === 'saci') e = new Saci(this.game, pos)
    else if (type === 'boi') e = new Boi(this.game, pos)
    else if (type === 'boss') {
      e = new Boss(this.game, new THREE.Vector3(0, 0, -34))
      this.boss = e
    }
    if (e) this.list.push(e)
    return e
  }

  countOfType(type) {
    return this.list.filter((e) => !e.dead && e.type === type).length
  }

  aliveCount() {
    return this.list.filter((e) => !e.dead).length
  }

  spawnProjectile(origin, dir, { speed = 10, damage = 10, color = 0xff5aa8, owner = null } = {}) {
    const mesh = new THREE.Group()
    const orb = new THREE.Mesh(new THREE.SphereGeometry(0.16, 8, 7), new THREE.MeshBasicMaterial({ color }))
    mesh.add(orb)
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(255,255,255,0.95)', 'rgba(255,80,160,0)'),
      color, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    }))
    glow.scale.set(1.4, 1.4, 1)
    mesh.add(glow)
    mesh.position.copy(origin)
    this.game.world.scene.add(mesh)
    this.projectiles.push({
      mesh, dir: dir.clone().normalize(), speed, damage, color, owner,
      life: 4.5, trail: 0,
    })
  }

  spawnShockwave(pos, { damage = 12, speed = 9, maxRadius = 34, color = 0xff3d8b } = {}) {
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.85, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    })
    const mesh = new THREE.Mesh(new THREE.RingGeometry(0.92, 1, 64), mat)
    mesh.rotation.x = -Math.PI / 2
    mesh.position.set(pos.x, 0.85, pos.z)
    mesh.scale.setScalar(1)
    this.game.world.scene.add(mesh)
    this.shockwaves.push({ mesh, radius: 1, speed, maxRadius, damage, hit: false, color })
  }

  raycast(origin, dir, maxDist = 70) {
    let best = null
    const center = new THREE.Vector3()
    for (const e of this.list) {
      if (e.dead) continue
      center.set(e.group.position.x, e.group.position.y + e.hitY, e.group.position.z)
      const oc = new THREE.Vector3().subVectors(center, origin)
      const tca = oc.dot(dir)
      if (tca < 0) continue
      const d2 = oc.lengthSq() - tca * tca
      const r2 = e.hitRadius * e.hitRadius
      if (d2 > r2) continue
      const thc = Math.sqrt(r2 - d2)
      const t = tca - thc
      if (t < 0 || t > maxDist) continue
      if (!best || t < best.dist) {
        best = {
          enemy: e,
          dist: t,
          point: origin.clone().addScaledVector(dir, t),
          center: center.clone(),
        }
      }
    }
    return best
  }

  findAimTarget(origin, dir, maxAngle = 0.1, maxDist = 70) {
    let best = null
    const to = new THREE.Vector3()
    for (const e of this.list) {
      if (e.dead) continue
      to.set(e.group.position.x, e.group.position.y + e.hitY, e.group.position.z).sub(origin)
      const dist = to.length()
      if (dist > maxDist || dist < 0.1) continue
      to.divideScalar(dist)
      const ang = Math.acos(clamp(to.dot(dir), -1, 1))
      const allowance = Math.max(maxAngle, Math.atan2(e.hitRadius, dist) * 0.85)
      if (ang < allowance) {
        const weight = ang - (1 - dist / maxDist) * 0.004
        if (!best || weight < best.weight) best = { enemy: e, weight, angle: ang }
      }
    }
    return best
  }

  damageInRadius(pos, radius, damage, source = null) {
    let hits = 0
    for (const e of this.list) {
      if (e.dead) continue
      const c = e.center()
      const d = c.distanceTo(pos)
      if (d < radius + e.hitRadius) {
        const falloff = clamp(1 - d / (radius + e.hitRadius) * 0.55, 0.45, 1)
        e.takeDamage(damage * falloff, c)
        hits++
      }
    }
    return hits
  }

  update(dt) {
    for (const e of this.list) {
      if (!e.dead) e.update(dt)
    }
    // remove dead non-boss entries
    for (let i = this.list.length - 1; i >= 0; i--) {
      const e = this.list[i]
      if (e.dead) {
        if (e.type === 'boss') this.boss = null
        this.list.splice(i, 1)
      }
    }

    // projectiles
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i]
      p.life -= dt
      p.mesh.position.addScaledVector(p.dir, p.speed * dt)
      p.mesh.rotation.y += dt * 4
      p.trail -= dt
      if (p.trail <= 0) {
        p.trail = 0.04
        this.game.effects.spawnParticles(p.mesh.position, 1, {
          color: p.color, color2: 0xffffff, speed: 0.6, spread: 0.05, life: 0.25,
          size: 0.35, gravity: 0, drag: 0.9,
        })
      }
      const pp = this.game.player.position
      const d = Math.hypot(p.mesh.position.x - pp.x, p.mesh.position.z - pp.z)
      const yHit = p.mesh.position.y > 0.4 && p.mesh.position.y < 2.3
      let remove = false
      if (d < 0.75 && yHit) {
        this.game.player.takeDamage(p.damage, p.mesh.position)
        this.game.effects.hit(p.mesh.position, p.color, 10)
        remove = true
      }
      if (p.life <= 0 || p.mesh.position.y < 0.1 || Math.hypot(p.mesh.position.x, p.mesh.position.z) > 32) remove = true
      if (remove) {
        this.game.effects.hit(p.mesh.position, p.color, 6)
        this.game.world.scene.remove(p.mesh)
        this.projectiles.splice(i, 1)
      }
    }

    // boss shockwaves
    const pp = this.game.player.position
    for (let i = this.shockwaves.length - 1; i >= 0; i--) {
      const s = this.shockwaves[i]
      s.radius += s.speed * dt
      const k = s.radius / s.maxRadius
      s.mesh.scale.setScalar(s.radius)
      s.mesh.material.opacity = 0.85 * (1 - k) + 0.1
      if (!s.hit) {
        const d = Math.hypot(pp.x - s.mesh.position.x, pp.z - s.mesh.position.z)
        if (Math.abs(d - s.radius) < 1.0) {
          const dealt = this.game.player.takeDamage(s.damage, s.mesh.position)
          if (dealt > 0) {
            s.hit = true
            this.game.effects.hit(this.game.player.eyePosition, 0xff3d8b, 12)
          }
        }
      }
      if (s.radius > s.maxRadius) {
        this.game.world.scene.remove(s.mesh)
        s.mesh.geometry.dispose()
        s.mesh.material.dispose()
        this.shockwaves.splice(i, 1)
      }
    }
  }
}

// Berimbau blaster + festa junina rocket launcher, with first-person viewmodel.
import * as THREE from 'three'
import { clamp, damp, rand, glowTexture, textTexture } from './utils.js'

export class WeaponSystem {
  constructor(game) {
    this.game = game
    this.current = 0
    this.weapons = ['berimbau', 'foguete']
    this.names = { berimbau: 'BERIMBAU', foguete: 'FOGUETE' }
    this.fireTimer = 0
    this.switchT = 0
    this.kick = 0
    this.flash = 0
    this.rocketAmmo = 3
    this.rocketMax = 3
    this.regen = 0
    this.rockets = []
    this.shotsFired = 0
    this.shotsHit = 0
    this.sway = new THREE.Vector2()
    this.bobOffset = new THREE.Vector2()

    this.scene = new THREE.Scene()
    this.camera = new THREE.PerspectiveCamera(56, 1, 0.01, 6)
    this.scene.add(this.camera)
    this.scene.add(new THREE.AmbientLight(0xfff0dc, 1.5))
    const key = new THREE.DirectionalLight(0xffd0a0, 2.6)
    key.position.set(0.6, 1.2, 1.4)
    this.scene.add(key)
    const rim = new THREE.DirectionalLight(0x4fe6d0, 1.4)
    rim.position.set(-1.2, 0.2, 0.6)
    this.scene.add(rim)
    const back = new THREE.DirectionalLight(0xff4f9a, 1.1)
    back.position.set(0.2, -0.6, -1)
    this.scene.add(back)

    this.root = new THREE.Group()
    this.root.position.set(0.3, -0.27, -0.62)
    this.camera.add(this.root)
    this.buildBerimbau()
    this.buildRocket()
    this.setWeapon(0, true)
  }

  buildBerimbau() {
    const g = new THREE.Group()
    const wood = new THREE.MeshStandardMaterial({ color: 0x9a5a2c, roughness: 0.55, metalness: 0.15 })
    const darkWood = new THREE.MeshStandardMaterial({ color: 0x4a2a18, roughness: 0.7 })
    const stringMat = new THREE.MeshBasicMaterial({ color: 0xffe2a0 })
    const glowMat = new THREE.MeshBasicMaterial({ color: 0xffb43d })

    // bow arc
    const bow = new THREE.Mesh(new THREE.TorusGeometry(0.26, 0.018, 6, 30, Math.PI * 1.05), wood)
    bow.rotation.set(0.2, 0.1, -1.1)
    g.add(bow)
    // gourd resonator
    const gourd = new THREE.Mesh(new THREE.SphereGeometry(0.11, 12, 10), darkWood)
    gourd.scale.set(1, 1.15, 0.8)
    gourd.position.set(-0.02, -0.19, 0.05)
    g.add(gourd)
    // string
    const string = new THREE.Mesh(new THREE.CylinderGeometry(0.004, 0.004, 0.5, 4), stringMat)
    string.position.set(0.0, 0.03, 0.02)
    string.rotation.z = 0.42
    g.add(string)
    // energy coil — the "blaster" part
    const coil = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.24, 12), new THREE.MeshStandardMaterial({ color: 0x1a1420, roughness: 0.4, metalness: 0.6 }))
    coil.rotation.x = Math.PI / 2
    coil.position.set(0.02, 0.08, -0.18)
    g.add(coil)
    for (let i = 0; i < 3; i++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.055, 0.008, 4, 14), glowMat)
      ring.position.set(0.02, 0.08, -0.26 + i * 0.06)
      g.add(ring)
    }
    const core = new THREE.Mesh(new THREE.SphereGeometry(0.03, 8, 7), glowMat)
    core.position.set(0.02, 0.08, -0.3)
    g.add(core)
    // grip
    const grip = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.17, 0.08), darkWood)
    grip.position.set(0.02, -0.06, 0.03)
    grip.rotation.x = 0.22
    g.add(grip)

    // little festa ribbon
    const ribbon = new THREE.Mesh(new THREE.PlaneGeometry(0.1, 0.24), new THREE.MeshBasicMaterial({ color: 0xff3d8b, side: THREE.DoubleSide }))
    ribbon.position.set(-0.14, -0.2, -0.03)
    ribbon.rotation.z = 0.3
    g.add(ribbon)

    const flash = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(255,235,180,1)', 'rgba(255,120,30,0)'),
      color: 0xffc35a, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0,
    }))
    flash.position.set(0.02, 0.08, -0.34)
    flash.scale.set(0.3, 0.3, 1)
    g.add(flash)
    this.berimbauFlash = flash
    this.berimbau = g
    this.root.add(g)
  }

  buildRocket() {
    const g = new THREE.Group()
    const tubeMat = new THREE.MeshStandardMaterial({ color: 0x2a7a5a, roughness: 0.55, metalness: 0.2 })
    const tube = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.085, 0.72, 14), tubeMat)
    tube.rotation.x = Math.PI / 2
    tube.position.set(0, 0.02, -0.18)
    g.add(tube)
    // festa stripes
    const stripeCols = [0xffcf3f, 0xff3d8b, 0xfff6e6]
    for (let i = 0; i < 3; i++) {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(0.081, 0.012, 5, 18), new THREE.MeshStandardMaterial({ color: stripeCols[i], roughness: 0.4 }))
      ring.position.set(0, 0.02, -0.4 + i * 0.2)
      g.add(ring)
    }
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.085, 0.18, 12), new THREE.MeshStandardMaterial({ color: 0xff7a2f, emissive: 0x6a2208, emissiveIntensity: 0.8, roughness: 0.4 }))
    tip.rotation.x = -Math.PI / 2
    tip.position.set(0, 0.02, -0.63)
    g.add(tip)
    const grip = new THREE.Mesh(new THREE.BoxGeometry(0.075, 0.2, 0.09), new THREE.MeshStandardMaterial({ color: 0x241420, roughness: 0.8 }))
    grip.position.set(0, -0.12, 0.03)
    grip.rotation.x = 0.25
    g.add(grip)
    const sight = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.06, 0.1), new THREE.MeshBasicMaterial({ color: 0x2ee6c8 }))
    sight.position.set(0, 0.11, -0.32)
    g.add(sight)
    const flash = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(255,230,170,1)', 'rgba(255,110,20,0)'),
      color: 0xffb44a, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0,
    }))
    flash.position.set(0, 0.02, -0.75)
    flash.scale.set(0.55, 0.55, 1)
    g.add(flash)
    this.rocketFlash = flash
    this.rocket = g
    this.root.add(g)
  }

  setWeapon(index, silent = false) {
    this.current = index
    this.switchT = 0.28
    this.berimbau.visible = index === 0
    this.rocket.visible = index === 1
    if (!silent) this.game.audio.switchWeapon()
    this.game.onWeaponChange?.(this.current)
  }

  switchWeapon() {
    if (this.switchT > 0.05) return
    this.setWeapon((this.current + 1) % this.weapons.length)
  }

  reset() {
    this.current = 0
    this.berimbau.visible = true
    this.rocket.visible = false
    this.fireTimer = 0
    this.switchT = 0
    this.rocketAmmo = this.rocketMax
    this.regen = 0
    this.kick = 0
    this.flash = 0
    this.shotsFired = 0
    this.shotsHit = 0
    for (const r of this.rockets) {
      this.game.world.scene.remove(r.group)
      r.group.traverse?.((o) => { o.geometry?.dispose?.(); o.material?.dispose?.() })
    }
    this.rockets.length = 0
    this.game.onWeaponChange?.(0)
  }

  update(dt, input) {
    this.fireTimer = Math.max(0, this.fireTimer - dt)
    this.switchT = Math.max(0, this.switchT - dt)
    this.kick = damp(this.kick, 0, 14, dt)
    this.flash = Math.max(0, this.flash - dt * 9)

    if (input.consumeSwitch()) this.switchWeapon()

    // rocket ammo regen
    if (this.rocketAmmo < this.rocketMax) {
      this.regen += dt
      if (this.regen >= 5.5) {
        this.regen = 0
        this.rocketAmmo++
        this.game.onAmmoChange?.(this.rocketAmmo)
      }
    }

    if (input.isFiring() && this.switchT <= 0.05) {
      this.tryFire()
    }

    this.updateViewmodel(dt)
    this.updateRockets(dt)
  }

  tryFire() {
    if (this.fireTimer > 0) return
    if (this.current === 0) {
      this.fireTimer = 0.115
      this.fireBerimbau()
    } else {
      if (this.rocketAmmo <= 0) {
        if (this.fireTimer <= 0) {
          this.fireTimer = 0.3
          this.game.audio.tone(180, 0.06, { type: 'square', gain: 0.05 })
          this.game.ui.toast('Sem foguetes — recarregando', 'warn', 1.2)
        }
        return
      }
      this.fireTimer = 0.85
      this.rocketAmmo--
      this.game.onAmmoChange?.(this.rocketAmmo)
      this.fireRocket()
    }
  }

  aim() {
    const origin = this.game.player.camera.position.clone()
    const dir = this.game.player.aimDirection
    const assistAngle = this.game.input.touch ? 0.085 : 0.032
    const assist = this.game.enemies.findAimTarget(origin, dir, assistAngle, 65)
    if (assist) {
      const c = assist.enemy.center()
      dir.copy(c).sub(origin).normalize()
    }
    return { origin, dir }
  }

  fireBerimbau() {
    const { origin, dir } = this.aim()
    const wallDist = this.game.world.rayDistance(origin, dir, 65)
    const hit = this.game.enemies.raycast(origin, dir, Math.min(65, wallDist))
    const muzzle = origin.clone().addScaledVector(dir, 0.55)
      .add(new THREE.Vector3(0, -0.12, 0))
    const right = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0, 1, 0)).normalize()
    muzzle.addScaledVector(right, 0.16)

    let end = origin.clone().addScaledVector(dir, Math.min(wallDist, 65))
    if (hit) {
      end.copy(hit.point)
      const killed = hit.enemy.takeDamage(10, hit.point)
      this.shotsHit++
      this.game.effects.hit(hit.point, 0xffcf3f, killed ? 12 : 6)
      this.game.onHit?.(killed, hit.enemy)
    }
    this.shotsFired++
    this.game.effects.tracer(muzzle, end, 0xffe6a0, 1)
    this.game.effects.muzzle(muzzle, dir)
    this.game.audio.shot()
    this.game.player.addRecoil(0.009 + rand(-0.002, 0.002), rand(-0.002, 0.002))
    this.kick = 1
    this.flash = 1
  }

  fireRocket() {
    const { origin, dir } = this.aim()
    const start = origin.clone().addScaledVector(dir, 0.7).add(new THREE.Vector3(0, -0.14, 0))
    const group = new THREE.Group()
    const body = new THREE.Mesh(
      new THREE.CylinderGeometry(0.05, 0.05, 0.42, 8),
      new THREE.MeshBasicMaterial({ color: 0xffcf3f })
    )
    body.rotation.x = Math.PI / 2
    group.add(body)
    const tip = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.16, 8), new THREE.MeshBasicMaterial({ color: 0xff3d8b }))
    tip.rotation.x = Math.PI / 2
    tip.position.z = -0.28
    group.add(tip)
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(255,220,160,0.95)', 'rgba(255,90,20,0)'),
      color: 0xffa63d, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    }))
    glow.scale.set(0.9, 0.9, 1)
    group.add(glow)
    group.position.copy(start)
    group.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, -1), dir)
    this.game.world.scene.add(group)
    this.rockets.push({ group, dir: dir.clone(), speed: 34, life: 2.4, trail: 0 })
    this.game.effects.muzzle(start, dir)
    this.game.effects.flash(start, 2.4, 0xffb35c, 0.12)
    this.game.audio.rocket()
    this.game.player.addRecoil(0.05, rand(-0.004, 0.004))
    this.kick = 1.6
    this.flash = 1.4
  }

  updateRockets(dt) {
    for (let i = this.rockets.length - 1; i >= 0; i--) {
      const r = this.rockets[i]
      r.life -= dt
      const step = r.speed * dt
      const prev = r.group.position.clone()
      r.group.position.addScaledVector(r.dir, step)
      r.trail -= dt
      if (r.trail <= 0) {
        r.trail = 0.025
        this.game.effects.spawnParticles(r.group.position, 1, {
          color: 0xffb35c, color2: 0x6a5a70, speed: 0.8, spread: 0.08,
          life: 0.5, size: 0.45, gravity: 0.4, drag: 0.95,
        })
      }
      let explode = false
      let hitPos = r.group.position.clone()
      // direct enemy proximity
      for (const e of this.game.enemies.list) {
        if (e.dead) continue
        const c = e.center()
        if (c.distanceTo(r.group.position) < e.hitRadius + 0.55) {
          explode = true
          hitPos = r.group.position.clone()
          break
        }
      }
      if (!explode) {
        const wall = this.game.world.rayDistance(prev, r.dir, step + 0.3)
        if (wall < step + 0.25) {
          explode = true
          hitPos = prev.clone().addScaledVector(r.dir, Math.max(0, wall - 0.15))
        }
      }
      if (r.group.position.y < 0.15 || Math.hypot(r.group.position.x, r.group.position.z) > 34) {
        explode = true
        hitPos = r.group.position.clone()
        hitPos.y = Math.max(hitPos.y, 0.2)
      }
      if (r.life <= 0) explode = true

      if (explode) {
        this.explode(hitPos)
        this.game.world.scene.remove(r.group)
        r.group.traverse((o) => { o.geometry?.dispose?.(); o.material?.dispose?.() })
        this.rockets.splice(i, 1)
      }
    }
  }

  explode(pos) {
    this.game.effects.explosion(pos, 1.25)
    this.game.audio.explosion()
    this.game.player.shake = Math.max(this.game.player.shake, 0.8)
    const hits = this.game.enemies.damageInRadius(pos, 4.4, 62)
    if (hits > 0) this.game.onExplosionHit?.(hits)
  }

  updateViewmodel(dt) {
    const p = this.game.player
    const look = p.lookVel
    const swayX = clamp(-look.x * 0.00022, -0.035, 0.035)
    const swayY = clamp(look.y * 0.00018, -0.03, 0.03)
    this.sway.x = damp(this.sway.x, swayX, 8, dt)
    this.sway.y = damp(this.sway.y, swayY, 8, dt)

    const bob = p.speedRatio
    const bx = Math.sin(p.bobTime * 0.5) * 0.006 * bob
    const by = Math.abs(Math.cos(p.bobTime * 0.5)) * 0.008 * bob
    const switchDrop = this.switchT > 0 ? Math.sin((1 - this.switchT / 0.28) * Math.PI) * -0.16 : 0

    this.root.position.x = damp(this.root.position.x, 0.3 + this.sway.x + bx, 12, dt)
    this.root.position.y = damp(this.root.position.y, -0.27 + this.sway.y + by + switchDrop, 12, dt)
    this.root.position.z = damp(this.root.position.z, -0.62 + this.kick * 0.045, 16, dt)
    this.root.rotation.x = damp(this.root.rotation.x, this.kick * 0.09, 14, dt)
    this.root.rotation.y = damp(this.root.rotation.y, this.sway.x * 0.6, 10, dt)
    this.root.rotation.z = damp(this.root.rotation.z, this.sway.y * 0.8, 10, dt)

    const f = clamp(this.flash, 0, 1.4)
    const activeFlash = this.current === 0 ? this.berimbauFlash : this.rocketFlash
    activeFlash.material.opacity = f
    activeFlash.scale.setScalar(0.3 + f * 0.35 + (this.current === 1 ? 0.2 : 0))
    const other = this.current === 0 ? this.rocketFlash : this.berimbauFlash
    other.material.opacity = 0
  }

  resize(aspect) {
    this.camera.aspect = aspect
    this.camera.updateProjectionMatrix()
  }

  get ammo() {
    return this.current === 0 ? Infinity : this.rocketAmmo
  }
  get name() {
    return this.names[this.weapons[this.current]]
  }
  get accuracy() {
    return this.shotsFired ? this.shotsHit / this.shotsFired : 0
  }
}

// Açaí, maracujá, guaraná and moedas — floating pickups.
import * as THREE from 'three'
import { rand, pick, glowTexture, TAU } from './utils.js'

export class PickupManager {
  constructor(game) {
    this.game = game
    this.list = []
  }

  reset() {
    for (const p of this.list) {
      this.game.world.scene.remove(p.group)
      p.group.traverse((o) => { o.geometry?.dispose?.(); o.material?.dispose?.() })
    }
    this.list.length = 0
  }

  spawn(type, pos) {
    const g = new THREE.Group()
    let glowColor = 0xffcf3f
    if (type === 'acai') {
      glowColor = 0xb05cff
      const bowl = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.2, 0.18, 12), new THREE.MeshLambertMaterial({ color: 0x5b3a2a }))
      bowl.position.y = 0.02
      g.add(bowl)
      const acai = new THREE.Mesh(new THREE.SphereGeometry(0.25, 12, 8, 0, TAU, 0, Math.PI / 2), new THREE.MeshLambertMaterial({ color: 0x5a1f8a, emissive: 0x2a0a4a, emissiveIntensity: 0.8 }))
      acai.position.y = 0.11
      g.add(acai)
      const straw = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 0.42, 5), new THREE.MeshLambertMaterial({ color: 0xffcf3f }))
      straw.position.set(0.1, 0.35, 0.02)
      straw.rotation.z = -0.4
      g.add(straw)
    } else if (type === 'shield') {
      glowColor = 0xffd54a
      const fruit = new THREE.Mesh(new THREE.SphereGeometry(0.22, 12, 9), new THREE.MeshLambertMaterial({ color: 0xffcf3f, emissive: 0x6a4a08, emissiveIntensity: 0.9 }))
      g.add(fruit)
      for (let i = 0; i < 3; i++) {
        const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.3, 4), new THREE.MeshLambertMaterial({ color: 0x2f8a4a }))
        leaf.position.set(Math.cos(i * 2.1) * 0.12, 0.22, Math.sin(i * 2.1) * 0.12)
        leaf.rotation.z = Math.cos(i * 2.1) * 0.9
        leaf.rotation.x = Math.sin(i * 2.1) * 0.9
        g.add(leaf)
      }
    } else if (type === 'rapid') {
      glowColor = 0xff3d5a
      const can = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 0.42, 10), new THREE.MeshLambertMaterial({ color: 0xc42430, emissive: 0x4a0810, emissiveIntensity: 0.8 }))
      g.add(can)
      const band = new THREE.Mesh(new THREE.CylinderGeometry(0.145, 0.145, 0.1, 10), new THREE.MeshLambertMaterial({ color: 0xffcf3f }))
      g.add(band)
      const top = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.14, 0.06, 10), new THREE.MeshLambertMaterial({ color: 0xb8b8c0 }))
      top.position.y = 0.23
      g.add(top)
    } else {
      glowColor = 0xffcf3f
      const coin = new THREE.Mesh(new THREE.TorusGeometry(0.19, 0.06, 6, 16), new THREE.MeshLambertMaterial({ color: 0xffcf3f, emissive: 0x6a4a08, emissiveIntensity: 0.9 }))
      g.add(coin)
      const inner = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.13, 0.02, 12), new THREE.MeshLambertMaterial({ color: 0xffe08a }))
      inner.rotation.x = Math.PI / 2
      g.add(inner)
    }

    const glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: glowTexture('rgba(255,255,255,0.9)', 'rgba(255,120,40,0)'),
      color: glowColor, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, opacity: 0.85,
    }))
    glow.scale.set(1.9, 1.9, 1)
    g.add(glow)

    const ground = new THREE.Mesh(
      new THREE.RingGeometry(0.32, 0.4, 20),
      new THREE.MeshBasicMaterial({ color: glowColor, transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false })
    )
    ground.rotation.x = -Math.PI / 2
    ground.position.y = -0.62
    g.add(ground)

    const p = new THREE.Vector3(pos.x, 0.95, pos.z)
    this.game.world.collide(p, 0.4)
    g.position.set(p.x, 0.95, p.z)
    this.game.world.scene.add(g)
    this.list.push({ type, group: g, life: 15, baseY: 0.95, phase: rand(0, TAU), color: glowColor })
  }

  update(dt) {
    const pp = this.game.player.position
    for (let i = this.list.length - 1; i >= 0; i--) {
      const p = this.list[i]
      p.life -= dt
      p.group.rotation.y += dt * 1.8
      p.group.position.y = p.baseY + Math.sin(this.game.world.time * 2.4 + p.phase) * 0.12
      if (p.life < 3.5) {
        p.group.visible = Math.sin(p.life * 16) > -0.2
      }
      const d = Math.hypot(p.group.position.x - pp.x, p.group.position.z - pp.z)
      if (d < 1.5 && p.life > 0) {
        this.game.effects.ring(p.group.position, { color: p.color, from: 0.2, to: 2.4, life: 0.4, flat: false })
        this.game.effects.spawnParticles(p.group.position, 14, { color: p.color, color2: 0xffffff, speed: 4, spread: 0.4, life: 0.5, size: 0.4, gravity: 1 })
        this.game.onPickup(p.type)
        this.game.world.scene.remove(p.group)
        p.group.traverse((o) => { o.geometry?.dispose?.(); o.material?.dispose?.() })
        this.list.splice(i, 1)
        continue
      }
      if (p.life <= 0) {
        this.game.world.scene.remove(p.group)
        p.group.traverse((o) => { o.geometry?.dispose?.(); o.material?.dispose?.() })
        this.list.splice(i, 1)
      }
    }
  }
}

// DOM HUD, screens, toasts and juice.
export class UI {
  constructor(game) {
    this.game = game
    this.$ = (id) => document.getElementById(id)
    this.el = {
      hud: this.$('hud'),
      touch: this.$('touch-ui'),
      menu: this.$('screen-menu'),
      pause: this.$('screen-pause'),
      over: this.$('screen-over'),
      win: this.$('screen-win'),
      wave: this.$('wave-num'),
      score: this.$('score'),
      health: this.$('health-fill'),
      shield: this.$('shield-fill'),
      shieldRow: document.querySelector('.shield-row'),
      weaponName: this.$('weapon-name'),
      weaponAmmo: this.$('weapon-ammo'),
      slots: document.querySelectorAll('.weapon-slots i'),
      dash: this.$('dash-fill'),
      dashMeter: this.$('dash-meter'),
      combo: this.$('combo'),
      comboNum: this.$('combo-num'),
      boss: this.$('boss-bar'),
      bossFill: this.$('boss-fill'),
      bossText: this.$('boss-hp-text'),
      announce: this.$('announce'),
      announceKicker: this.$('announce-kicker'),
      announceTitle: this.$('announce-title'),
      announceSub: this.$('announce-sub'),
      hitmarker: this.$('hitmarker'),
      crosshair: this.$('crosshair'),
      vignette: this.$('damage-vignette'),
      pickupFlash: this.$('pickup-flash'),
      toastStack: this.$('toast-stack'),
      fade: this.$('fade'),
      rotate: this.$('rotate-hint'),
      best: this.$('best-score'),
      soundHud: this.$('btn-sound-hud'),
      quality: this.$('quality-label'),
      tiltBtns: [this.$('btn-tilt'), this.$('btn-tilt-pause')],
      soundBtns: [this.$('btn-sound-pause')],
    }
    this.cache = {}
    this.announceTimer = null
    this.rotateTimer = null
    this.hitTimer = null
    this.damageTimer = null
    this.pickupTimer = null
    this.toasts = []
  }

  showScreen(name) {
    const screens = { menu: this.el.menu, pause: this.el.pause, over: this.el.over, win: this.el.win }
    for (const [k, s] of Object.entries(screens)) {
      if (!s) continue
      s.classList.toggle('hidden', k !== name)
    }
  }

  hideScreens() {
    this.showScreen(null)
  }

  setPlaying(playing) {
    this.el.hud.classList.toggle('hidden', !playing)
    this.el.touch.classList.toggle('hidden', !(playing && this.game.input.touch))
    if (!playing) {
      this.el.hud.classList.add('hidden')
      this.el.touch.classList.add('hidden')
      this.hideBoss()
    }
  }

  updateHUD() {
    const g = this.game
    const p = g.player
    const w = g.weapons

    const hp = Math.round(p.healthPct * 100)
    if (this.cache.hp !== hp) {
      this.cache.hp = hp
      this.el.health.style.width = `${hp}%`
      this.el.health.classList.toggle('low', hp <= 30)
    }
    const sh = Math.round(p.shieldPct * 100)
    if (this.cache.sh !== sh) {
      this.cache.sh = sh
      this.el.shield.style.width = `${sh}%`
      this.el.shieldRow.classList.toggle('on', p.shield > 0.5)
    }
    if (this.cache.score !== g.score) {
      this.cache.score = g.score
      this.el.score.textContent = g.score.toLocaleString('pt-BR')
    }
    if (this.cache.wave !== g.wave) {
      this.cache.wave = g.wave
      this.el.wave.textContent = Math.min(g.wave, 5)
    }
    if (this.cache.weapon !== w.current) {
      this.cache.weapon = w.current
      this.el.weaponName.textContent = w.name
      this.el.slots.forEach((s, i) => s.classList.toggle('on', i === w.current))
    }
    const ammoText = w.current === 0 ? '∞' : `${w.rocketAmmo}`
    if (this.cache.ammo !== ammoText) {
      this.cache.ammo = ammoText
      this.el.weaponAmmo.textContent = ammoText
    }
    const dash = Math.round(p.dashPct * 100)
    if (this.cache.dash !== dash) {
      this.cache.dash = dash
      this.el.dash.style.width = `${dash}%`
    }
    const btnDash = document.getElementById('btn-dash')
    btnDash?.classList.toggle('cooldown', !p.dashReady)

    const showCombo = g.combo >= 2 && g.state === 'playing'
    this.el.combo.classList.toggle('show', showCombo)
    if (showCombo && this.cache.combo !== g.combo) {
      this.cache.combo = g.combo
      this.el.comboNum.textContent = g.multiplier.toFixed(1)
    }

    // crosshair hot state when aiming at an enemy
    const origin = p.camera.position
    const dir = p.aimDirection
    const aim = g.enemies.findAimTarget(origin, dir, g.input.touch ? 0.09 : 0.04, 60)
    this.el.crosshair.classList.toggle('hot', !!aim)
  }

  updateBoss() {
    const boss = this.game.enemies.boss
    if (!boss || boss.dead) { this.hideBoss(); return }
    this.el.boss.classList.remove('hidden')
    const pct = Math.max(0, boss.hp / boss.maxHp)
    this.el.bossFill.style.width = `${pct * 100}%`
    this.el.bossText.textContent = `${Math.ceil(pct * 100)}%`
  }

  hideBoss() {
    this.el.boss.classList.add('hidden')
  }

  hit(kill = false) {
    const h = this.el.hitmarker
    h.classList.remove('show', 'kill')
    void h.offsetWidth
    h.classList.add('show')
    if (kill) h.classList.add('kill')
  }

  damage() {
    const v = this.el.vignette
    v.classList.add('hit')
    clearTimeout(this.damageTimer)
    this.damageTimer = setTimeout(() => v.classList.remove('hit'), 130)
  }

  pickupFlash() {
    const f = this.el.pickupFlash
    f.classList.add('on')
    clearTimeout(this.pickupTimer)
    this.pickupTimer = setTimeout(() => f.classList.remove('on'), 90)
  }

  announce(kicker, title, sub = '', duration = 2200) {
    const a = this.el.announce
    this.el.announceKicker.textContent = kicker
    this.el.announceTitle.textContent = title
    this.el.announceSub.textContent = sub
    a.classList.remove('hidden')
    requestAnimationFrame(() => a.classList.add('show'))
    clearTimeout(this.announceTimer)
    this.announceTimer = setTimeout(() => {
      a.classList.remove('show')
      setTimeout(() => a.classList.add('hidden'), 400)
    }, duration)
  }

  toast(text, tone = '', duration = 2.2) {
    const el = document.createElement('div')
    el.className = `toast ${tone}`
    el.innerHTML = text
    this.el.toastStack.appendChild(el)
    while (this.el.toastStack.children.length > 3) {
      this.el.toastStack.firstChild.remove()
    }
    setTimeout(() => {
      el.classList.add('out')
      setTimeout(() => el.remove(), 320)
    }, duration * 1000)
  }

  rotateHint(show) {
    if (!show) {
      this.el.rotate.classList.add('hidden')
      return
    }
    this.el.rotate.classList.remove('hidden')
    clearTimeout(this.rotateTimer)
    this.rotateTimer = setTimeout(() => this.el.rotate.classList.add('hidden'), 5500)
  }

  setTilt(on) {
    this.el.tiltBtns.forEach((b) => b?.setAttribute('aria-pressed', String(on)))
  }

  setSound(on) {
    this.el.soundBtns.forEach((b) => {
      b?.setAttribute('aria-pressed', String(on))
      const sw = b?.querySelector('.switch')
      sw?.classList.toggle('on', on)
    })
    this.el.soundHud?.classList.toggle('muted', !on)
  }

  setQuality(label) {
    if (this.el.quality) this.el.quality.textContent = label
  }

  setBest(score) {
    this.el.best.textContent = Number(score).toLocaleString('pt-BR')
  }

  fade(on) {
    this.el.fade.classList.toggle('on', on)
  }

  resetCache() {
    this.cache = {}
    this.el.combo.classList.remove('show')
    this.hideBoss()
  }
}

